Component(
  dsl: 1, id: "market/fulfilment-badges", name: "Delivery and collection badges", kind: Kind.section,
  description: "Which of delivery and collection the chosen store offers.",
  variants: [Variant(id: "default", label: "Default", build:
    Wrap(spacing: Space.xs, runSpacing: Space.xs, children: [
      If(condition: store.accepts_delivery, then: Badge(label: "Delivery", tone: Tone.success)),
      If(condition: store.accepts_collect, then: Badge(label: "Collection", tone: Tone.primary))
    ])
  )], data: [Data(name: "store", from: Client.store(), fetch: "client", type: Store)],
)
